{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Tolfenamic acid, a small oral NSAID with high assay-transfer score, showed absolute oral bioavailability of 63.2% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Para-aminobenzoic acid, sharing the para-aminophenyl motif with the query, showed oral bioavailability of 90.1% in patients, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Selurampanel, a heteroaromatic sulfonamide-like oral drug with high transferability, had estimated absolute oral bioavailability of 60-70% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Amrinone, a small heteroaromatic oral drug, showed oral bioavailability of 90-95% in healthy subjects, supporting high absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PF-592379, a small oral drug with high transfer score, was predicted to have complete absorption and clinical oral bioavailability >60%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "6-MNA, a small aromatic carboxylic acid metabolite, had absolute oral bioavailability of 38%, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib, a complex oral drug with high transferability, had absolute oral bioavailability of 25.3% in healthy subjects, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Gallium maltolate showed oral bioavailability of at least 25-57% in healthy humans, supporting high F for a small absorbable molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pyridoxal 5'-phosphate from a delayed-release tablet had oral bioavailability of 23.7%, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Para-aminosalicylic acid, structurally related to the para-aminophenyl portion of the query, showed oral bioavailability of 50-60% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues, with high assay-transfer scores, show absolute oral bioavailability values above the 20% threshold, ranging from about 24% to 100% in humans. No evidence supports low bioavailability. The query is a small sulfonamide with a para-aminophenyl group and isoxazole ring, consistent with well-absorbed oral drugs. Therefore, high oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability measurement exists for the query molecule itself.",
    "Most evidence comes from structurally related but not identical molecules; reliance is placed on high assay-transfer scores and shared physicochemical features.",
    "Some records use unspecified bioavailability report types or special patient populations, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

